package android.app; import android.content.*; public class AlertDialog implements DialogInterface { public void dismiss(){} public static class Builder { public Builder(Context c){} public Builder setTitle(CharSequence s){return this;} public Builder setMessage(CharSequence s){return this;} public Builder setPositiveButton(CharSequence s,DialogInterface.OnClickListener l){return this;} public Builder setNegativeButton(CharSequence s,DialogInterface.OnClickListener l){return this;} public Builder setOnCancelListener(DialogInterface.OnCancelListener l){return this;} public AlertDialog show(){return new AlertDialog();} } }